"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type MouseEvent, useRef } from "react";
import { flushSync } from "react-dom";

import { cn } from "@/lib/utils";

/** How the new theme replaces the old one. */
export type ThemeTransitionEffect = "circle" | "split";

/** Props for a theme toggle. The parent owns the theme and applies it in `onThemeChange`. */
export interface ThemeTransitionToggleProps {
  theme: "light" | "dark";
  /** Applies the theme, for example next-themes' `setTheme`. It must update the page before it returns or in the commit it starts. */
  onThemeChange: (theme: "light" | "dark") => void;
  effect?: ThemeTransitionEffect;
  className?: string;
}

// A singular arrival, so a long front-loaded ease-out: most of the reveal is
// over in the first 200 milliseconds and the rest is a settle.
const REVEAL_MS = 600;
const REVEAL_EASING = "cubic-bezier(0.19, 1, 0.22, 1)";
const SPIN: Transition = { type: "spring", stiffness: 300, damping: 35, mass: 1 };
const INSTANT: Transition = { duration: 0 };
// The browser cross-fades the two snapshots by default. This turns that off
// for the length of one change, so only the reveal shows.
const SNAPSHOT_RULES =
  "::view-transition-old(root),::view-transition-new(root){animation:none;mix-blend-mode:normal}";

const toRem = (pixels: number) => {
  const rootSize = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
  return `${pixels / rootSize}rem`;
};

/**
 * Changes the theme with a reveal. `circle` grows the new theme from a point,
 * such as the button that was pressed. `split` opens it from the middle out.
 * Browsers without view transitions, and people who ask for reduced motion,
 * get the new theme at once.
 */
export function transitionTheme(apply: () => void, effect: ThemeTransitionEffect, origin?: { x: number; y: number }) {
  if (!("startViewTransition" in document) || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    apply();
    return;
  }

  const style = document.createElement("style");
  style.textContent = SNAPSHOT_RULES;
  document.head.append(style);

  const transition = document.startViewTransition(() => flushSync(apply));
  transition.ready
    .then(() => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      const x = origin?.x ?? width / 2;
      const y = origin?.y ?? height / 2;
      // The circle must reach the farthest corner from where it starts.
      const radius = Math.hypot(Math.max(x, width - x), Math.max(y, height - y));
      const at = `at ${toRem(x)} ${toRem(y)}`;
      const clipPath =
        effect === "circle"
          ? [`circle(0rem ${at})`, `circle(${toRem(radius)} ${at})`]
          : ["inset(0% 50% 0% 50%)", "inset(0% 0% 0% 0%)"];
      document.documentElement.animate(
        { clipPath },
        { duration: REVEAL_MS, easing: REVEAL_EASING, pseudoElement: "::view-transition-new(root)" },
      );
    })
    // A skipped transition still applied the theme; only the reveal is lost.
    .catch(() => undefined);
  transition.finished.finally(() => style.remove());
}

/**
 * A button that switches between light and dark. The new theme spreads out
 * from the button, or opens from the middle with `effect="split"`.
 */
export function ThemeTransitionToggle({ theme, onThemeChange, effect = "circle", className }: ThemeTransitionToggleProps) {
  const reduceMotion = useReducedMotion();
  const button = useRef<HTMLButtonElement>(null);
  const isDark = theme === "dark";

  const toggle = (event: MouseEvent<HTMLButtonElement>) => {
    const next = isDark ? "light" : "dark";
    // A keyboard press reports no pointer, so the reveal starts from the button's centre.
    const box = button.current?.getBoundingClientRect();
    const fromPointer = event.clientX !== 0 || event.clientY !== 0;
    const origin = fromPointer
      ? { x: event.clientX, y: event.clientY }
      : box && { x: box.left + box.width / 2, y: box.top + box.height / 2 };
    transitionTheme(() => onThemeChange(next), effect, origin);
  };

  return (
    <button
      ref={button}
      type="button"
      aria-label="Dark theme"
      aria-pressed={isDark}
      onClick={toggle}
      className={cn(
        "grid size-11 cursor-pointer touch-manipulation place-items-center rounded-full border border-border bg-card text-foreground outline-none",
        "hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition-colors active:scale-95",
        className,
      )}
    >
      <span aria-hidden="true" className="relative grid size-5 place-items-center">
        {/* The sun turns away as the moon turns in, so the icon shows the theme that is on. */}
        <motion.svg
          viewBox="0 0 20 20"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          className="absolute inset-0 size-5"
          initial={false}
          animate={{ rotate: isDark ? -90 : 0, scale: isDark ? 0.5 : 1, opacity: isDark ? 0 : 1 }}
          transition={reduceMotion ? INSTANT : SPIN}
        >
          <circle cx="10" cy="10" r="3.5" fill="currentColor" stroke="none" />
          {[0, 45, 90, 135, 180, 225, 270, 315].map((angle) => (
            <line key={angle} x1="10" y1="1.75" x2="10" y2="3.5" transform={`rotate(${angle} 10 10)`} />
          ))}
        </motion.svg>
        <motion.svg
          viewBox="0 0 20 20"
          fill="currentColor"
          className="absolute inset-0 size-5"
          initial={false}
          animate={{ rotate: isDark ? 0 : 90, scale: isDark ? 1 : 0.5, opacity: isDark ? 1 : 0 }}
          transition={reduceMotion ? INSTANT : SPIN}
        >
          <path d="M16.5 12.6A7 7 0 0 1 7.4 3.5a7 7 0 1 0 9.1 9.1Z" />
        </motion.svg>
      </span>
    </button>
  );
}
